import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Zona } from '../../zonas/entities/zona.entity';
import { Jardinero } from '../../jardineros/entities/jardinero.entity';

@Injectable()
export class AsignarJardineroRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Zona) private readonly zonas: Repository<Zona>,
    @InjectRepository(Jardinero) private readonly jardineros: Repository<Jardinero>
  ) {}

  buscarZonaRepository(zonaId: number) {
    return this.zonas.findOneBy({ id: zonaId });
  }

  buscarJardineroRepository(jardineroId: number) {
    return this.jardineros.findOneBy({ id: jardineroId });
  }

  async asignarJardineroRepository(zonaId: number, jardineroId: number, rol: string) {
    const asignacion = { zonaId, jardineroId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarJardineroRepository } from './repository';

@Injectable()
export class AsignarJardineroService {
  constructor(private readonly repository: AsignarJardineroRepository) {}

  async asignarJardineroService(zonaId: number, jardineroId: number, rol: string) {
    const zona = await this.repository.buscarZonaRepository(zonaId);
    const jardinero = await this.repository.buscarJardineroRepository(jardineroId);
    if (!zona || !jardinero) {
      throw new NotFoundException('No existe la zona o el jardinero');
    }

    try {
      return await this.repository.asignarJardineroRepository(zonaId, jardineroId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El jardinero ya está asignado a esa zona');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarJardineroService } from './service';

@Controller('zonas/:zonaId/asignaciones')
export class AsignarJardineroController {
  constructor(private readonly service: AsignarJardineroService) {}

  @Post()
  asignar(@Param('zonaId') zonaId: string, @Body() datos: { jardineroId: number; rol: string }) {
    return this.service.asignarJardineroService(Number(zonaId), datos.jardineroId, datos.rol);
  }
}
